create role anon;create role authenticated;create role service_role bypassrls;
create schema auth;
create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
create table auth.users(id uuid primary key,raw_app_meta_data jsonb,banned_until timestamptz);
insert into auth.users values('11111111-1111-4111-8111-111111111111','{"role":"EJECUTIVA_VENTAS"}',null),('22222222-2222-4222-8222-222222222222','{"role":"EJECUTIVA_VENTAS"}',null);
create table clients(id uuid primary key default gen_random_uuid(),legal_name text,rut text unique,business_activity text,general_email text,phone text,country text,commune text,address text,account_executive_id uuid,status text,currency text,credit_days int,health text,health_factors jsonb,created_at timestamptz default now());
create table client_contacts(id uuid primary key default gen_random_uuid(),client_id uuid references clients(id),name text,email text,phone text,is_primary boolean,billing_contact boolean,technical_contact boolean,commercial_contact boolean,portal_access boolean,status text,portal_status text);
create table client_events(id uuid primary key default gen_random_uuid(),client_id uuid references clients(id),event_type text,title text,description text,visibility text,metadata jsonb);
create table leads(id uuid primary key default gen_random_uuid(),company_name text,contact_name text,email text,phone text,rut text,website text,interest text,notes text,assigned_to uuid,status text,assigned_by uuid,assigned_at timestamptz,created_by uuid,client_id uuid);
create table quotes(id uuid primary key default gen_random_uuid(),client_id uuid references clients(id),lead_id uuid references leads(id),opportunity_id uuid,company_name text,contact_name text,contact_email text,owner_id uuid,status text,currency text,subtotal numeric,discount_total numeric,net_amount numeric,tax_rate numeric,tax_amount numeric,total_amount numeric,valid_until date,payment_terms text,commercial_terms text,notes text,document_id uuid,sent_at timestamptz,accepted_at timestamptz,quote_number text default 'COT-SYNTHETIC',created_at timestamptz default now(),updated_at timestamptz default now());
create table quote_items(id uuid primary key default gen_random_uuid(),quote_id uuid references quotes(id),catalog_service_id uuid,description text,quantity numeric,unit_price numeric,discount_percent numeric,taxable boolean,subtotal numeric,position integer);
create table quote_payment_plans(id uuid,quote_id uuid);
create table quote_payment_installments(id uuid primary key default gen_random_uuid(),quote_id uuid references quotes(id),status text,paid_amount numeric,amount numeric,invoice_storage_path text,marked_paid_by uuid,currency text,paid_at timestamptz,sequence integer,sii_folio integer,sii_document_type integer);
create table sales(id uuid primary key default gen_random_uuid(),quote_id uuid references quotes(id),owner_id uuid);
create table tax_documents(id uuid primary key default gen_random_uuid(),folio integer);
create table invoices(id uuid primary key default gen_random_uuid(),sale_id uuid,status text,document_type_code integer,amount_credited numeric default 0,currency text,net_amount numeric,exempt_amount numeric default 0,total_amount numeric,invoice_number text,tax_document_id uuid);
create table payments(id uuid primary key default gen_random_uuid(),status text,currency text);
create table payment_allocations(id uuid primary key default gen_random_uuid(),invoice_id uuid,payment_id uuid,amount numeric,reversed_at timestamptz,allocated_at timestamptz default now());
create function zyteron_accept_commercial_proposal(target_quote uuid,actor_id uuid) returns boolean language plpgsql as $$begin update quotes set status='ACCEPTED',accepted_at=now() where id=target_quote and status in('SENT','NEGOTIATING');return found;end$$;
alter table clients enable row level security;
create policy old_client_reader on clients for select to authenticated using(true);
grant usage on schema public,auth to authenticated,service_role;
grant select on clients to authenticated;
grant all on all tables in schema public to service_role;
grant select on auth.users to service_role;
